#!/bin/sh
# Railway wrapper for Filestash.
# - all state (config.json, SQLite db, search index, plugins, logs) lives on the
#   volume at /app/data/state; /app/data/state/files is a ready-made folder for the
#   "Local" storage backend
# - FILESTASH_ADMIN_PASSWORD (plain text, generated by the template) is hashed with
#   bcrypt into ADMIN_PASSWORD, which Filestash applies to the admin console on boot
# - listens on $PORT (default 8334)
# - first boot only: a "Local" storage connection rooted at /app/data/state/files
set -eu

STATE=/app/data/state
mkdir -p "$STATE/config" "$STATE/db" "$STATE/log" "$STATE/plugins" "$STATE/search" "$STATE/certs" "$STATE/files"

# First boot only: enable one "Local" storage connection so the Files page works
# right after deploy (log in with the admin password, files land on the volume).
# Filestash adds its secret key and the admin hash to this file itself. Remove or
# replace the connection later in Admin > Storage; this file is never rewritten.
if [ ! -s "$STATE/config/config.json" ]; then
  printf '%s\n' '{"connections":[{"type":"local","label":"Local","path":"/app/data/state/files/"}]}' > "$STATE/config/config.json"
fi

if [ -n "${FILESTASH_ADMIN_PASSWORD:-}" ]; then
  ADMIN_PASSWORD=$(perl -e '
    my $p = $ENV{FILESTASH_ADMIN_PASSWORD};
    open(my $r, "<", "/dev/urandom") or die "urandom: $!\n";
    read($r, my $b, 22) == 22 or die "urandom short read\n";
    my @c = (".", "/", "A".."Z", "a".."z", "0".."9");
    my $s = join("", map { $c[ord($_) % 64] } split(//, $b));
    my $h = crypt($p, "\$2b\$10\$" . $s);
    die "bcrypt hashing failed\n" unless defined($h) && $h =~ /^\$2b\$10\$.{53}$/;
    print $h;')
  export ADMIN_PASSWORD
fi
unset FILESTASH_ADMIN_PASSWORD

export FILESTASH_PORT="${PORT:-${FILESTASH_PORT:-8334}}"
export HOME="$STATE/files"

if [ "$(id -u)" = "0" ]; then
  # Railway volumes are mounted root-owned: hand them to the app user, then drop root.
  find "$STATE" -xdev \( ! -user filestash -o ! -group filestash \) -exec chown filestash:filestash {} +
  exec setpriv --reuid=filestash --regid=filestash --init-groups /app/filestash "$@"
fi
exec /app/filestash "$@"
